let a = [3, 8, 15, 21, 30, 42, 57, 64];
let target = 30;
let lo = 0;
let hi = a.length - 1;
let found = -1;
while (lo <= hi) {
  let mid = Math.floor((lo + hi) / 2);
  if (a[mid] === target) {
    found = mid;
    break;
  } else if (a[mid] < target) {
    lo = mid + 1;
  } else {
    hi = mid - 1;
  }
}
